!function(){"use strict";app.factory("transferenciaBodegaService",(function($injector){let mS=$injector.get("mainService"),url="/TransferenciaBodega/";return{getAll:getAll,insert:insert,update:update,anular:anular};function getAll(query){return mS.getData("get",`${url}Get?json=${JSON.stringify(query)}`).then(response=>{if("0"==response.code)throw response;if("1"==response.code){let results;return(JSON.parse(response.payload)||[]).map(item=>({idTransferenciaBodega:item.idTransferenciaBodega,idTipoDocumento:item.idTipoDocumento,nroDoc:item.nroDoc,fechaEmision:item.fechaEmision,estadoDesc:item.estadoDesc,estadoCodigo:item.estadoCodigo,total:item.total,bodegaOrigen:item.bodegaOrigen,bodegaDestino:item.bodegaDestino,rowColor:item.rowColor}))}}).catch(err=>{throw err})}function insert(query){return mS.getData("post",`${url}Insert`,query).then(response=>{if("0"==response.code)throw response;return response}).catch(err=>{throw err})}function update(id,query){return mS.getData("put",`${url}Update?id=`+id,query).then(response=>{if("0"==response.code)throw response;return response}).catch(err=>{throw err})}function anular(id){return mS.getData("delete",`${url}Delete?id=`+id).then(response=>{if("0"==response.code)throw response;return response}).catch(err=>{throw err})}}))}(window.angular);